function showDesc(show, hide) {
	if (show == 'Addon') {
		document.getElementById('addon' + show).style.display = "";
		document.getElementById('tab' + show).className += " over";
		document.getElementById('addon' + hide).style.display = "none";
		document.getElementById('tab' + hide).className = hide.toLowerCase();
	} else if (show == 'Version') {
		document.getElementById('addon' + show).style.display = "";
		document.getElementById('tab' + show).className += " over";
		document.getElementById('addon' + hide).style.display = "none";
		document.getElementById('tab' + hide).className = hide.toLowerCase();
	}
}
