function addonpdsCmp(code) {
	switch (code) {
		case 'write':
			var url="write.php";
			location.href = url;
			break;
		case 'modify':
			var url="write.php?idx=13140&rurl=%2Fdataninfo%2Faddonpds%2Fdetail.php%3Fidx%3D13140";
			location.href = url;
			break;
		case 'delete':
			var ans = confirm("정말로 삭제하시겠습니까?\n\n(삭제후 복구가 불가능합니다)");
			if (!ans) return;

			var url="write_delete.php?idx=13140&rurl=%2Fdataninfo%2Faddonpds%2Flist.php";
			location.href = url;
			break;
		case 'list':
			var url="/dataninfo/addonpds/list.php";
			location.href = url;
			break;
	}
}
